"""**Задание 5 (1)**"""

import re

NAMES = [
    "Иванов И. И.",
    "И. И. Иванов",
    "Иванов И.И.",
    "А.С. Пушкин",
    "Пушкин А.С.",
    "Д. М. Шеберле",
    "М. Кюри",
    "Ж.К. Ван Дамм",
]

surname = r'[А-ЯЁ][а-яё]+(?:\s+[А-ЯЁ][а-яё]+)?'

pattern = re.compile(
    rf'(?:(?P<s>{surname})\s*(?P<i1>[А-ЯЁ])\.\s*(?P<i2>[А-ЯЁ])?\.|'
    rf'(?P<i3>[А-ЯЁ])\.\s*(?P<i4>[А-ЯЁ])?\.?\s*(?P<t>{surname}))'
)

for name in NAMES:
    m = pattern.fullmatch(name)
    g = m.groupdict()
    s = g['s'] or g['t']
    i1 = g['i1'] or g['i3']
    i2 = g['i2'] or g['i4']
    print(f"{s} {i1}." + (f"{i2}." if i2 else ""))

